def create_site_pages(apps, schema_editor):
    Page = apps.get_model('core', 'Page')
    database = schema_editor.connection.alias

    for site_path, slug, title in SITE_PAGES:
        if Page.objects.using(database).filter(site_path=site_path).exists():
            continue

        unique_slug = slug
        suffix = 1
        while Page.objects.using(database).filter(slug=unique_slug).exists():
            unique_slug = f'{slug}-site-{suffix}'
            suffix += 1

        Page.objects.using(database).create(
            title=title,
            slug=unique_slug,
            site_path=site_path,
            status='published',
            is_front_page=(
                site_path == '/'
                and not Page.objects.using(database).filter(is_front_page=True).exists()
            ),
        )


def remove_site_pages(apps, schema_editor):
    Page = apps.get_model('core', 'Page')
    database = schema_editor.connection.alias
